  ('f75bf818-b0f2-5f98-b35c-8cdcabaaa4fc', 'ea65b685-d0c0-5aa8-bb8d-d6bb01f68d36', 'Black hole', 'In a DFD, the process "2 Record payment" has an arrow coming in from the Customer but no arrows going out. Explain why this is an error.', 'short_answer', 2, 'medium', 'explain', 'AI', 11, 'b670c685-56c9-5476-89b6-b0c02cd8dec7', '8ea8e9f4-22e7-5b92-8d15-e385f039857d', '{"answer_lines":3}'::jsonb, 'original', null, true, 'published', null, null, 0),
  ('295aba5c-8cb8-517c-8121-8d9bd9911141', 'ea65b685-d0c0-5aa8-bb8d-d6bb01f68d36', 'Entity to store', 'A student draws an arrow labelled "new member details" from the external entity **Member** directly to the data store **D1 Members**. Explain the error and how to correct it.', 'short_answer', 2, 'medium', 'explain', 'AI', 11, 'b670c685-56c9-5476-89b6-b0c02cd8dec7', '8ea8e9f4-22e7-5b92-8d15-e385f039857d', '{"answer_lines":3}'::jsonb, 'original', null, true, 'published', null, null, 0),
