  ('d264a294-cf05-58dd-b9ac-1d7ce85264af', 'ea65b685-d0c0-5aa8-bb8d-d6bb01f68d36', 'Buses and registers', 'Match each component to its role when memory is accessed.', 'matching', 4, 'easy', 'identify', 'AUTO', 12, '60897a48-c2f2-526e-b15e-c52852e09a07', 'e4c53106-09e0-5ad8-9665-876f37a5fc01', '{"left":[{"key":"L1","text":"Address bus"},{"key":"L2","text":"Data bus"},{"key":"L3","text":"MAR"},{"key":"L4","text":"MDR"}],"right":[{"key":"R1","text":"Carries the address of the location from the CPU to memory"},{"key":"R2","text":"Carries the data between the CPU and memory"},{"key":"R3","text":"Register holding the address to be accessed"},{"key":"R4","text":"Register holding the data read or to be written"}]}'::jsonb, 'original', null, true, 'published', null, null, 0),
