    $stmt = mysqli_prepare($conn, "INSERT INTO Book (Title, Price) VALUES (?, ?)");
    mysqli_stmt_bind_param($stmt, "sd", $title, $price);
    if (mysqli_stmt_execute($stmt)) echo "Book added";
    else echo "Error: " . mysqli_error($conn);
}
?>
