  ('e017b423-9b4d-53da-bab0-37fa1567fa8e', '8e295cdb-0657-531a-a523-68a75ffaaea6', 1, true, '172.168.10.45 (C D A B) (1)', '[{"criterion":"172.168.10.45","marks":1}]'::jsonb, '172.168.10.45', '{"values":["172.168.10.45","CDAB","C D A B"]}'::jsonb, null, null),
