  ('b58532ab-de7e-5e48-8131-fb3cacdbf012', '8298eca8-19f6-5bba-b1cc-aa3e42324a0a', 1, true, 'Bespoke / custom-written (1)', '[{"criterion":"Bespoke","marks":1}]'::jsonb, 'Bespoke software.', '{"values":["bespoke","bespoke software","custom","custom-written","custom written","custom software","custom-written software","bespoke application","tailor-made","tailor made"]}'::jsonb, null, null),
  ('6f558267-837b-553b-99e0-bc35befed860', '8c02595f-1bd1-515e-986c-1d6a574ea4b6', 1, true, 'Reason (1) + expansion (1), e.g.
