- loop through the meals (1)
- skips portions < 1 (1)
- inserts BookingItem with BookingID, MealID, Portions (1)', '[{"criterion":"Read","marks":1},{"criterion":"Booking insert","marks":1},{"criterion":"insert_id","marks":1},{"criterion":"Loop","marks":1},{"criterion":"Check","marks":1},{"criterion":"Item insert","marks":1}]'::jsonb, '```php
<?php
$pupil = (int)$_POST["pupil"];
$meals = $_POST["meal"];
$portions = $_POST["portions"];
mysqli_query($conn, "INSERT INTO Booking (PupilID, BookingDate) VALUES ($pupil, CURDATE())");
$id = mysqli_insert_id($conn);
for ($i = 0; $i < count($meals); $i++) {
    $p = (int)$portions[$i];
    if ($p < 1) continue;
    $m = (int)$meals[$i];
    mysqli_query($conn, "INSERT INTO BookingItem (BookingID, MealID, Portions) VALUES ($id, $m, $p)");
}
?>
