  ('ad96774b-ee1f-5be5-bdb9-1d4b137e5ab1', '51e2cc54-c62b-5153-9420-2a53e14ac621', 1, true, 'Any two (1 each): sources outside the database; paraphrasing / translation; images / ideas; false positives; privacy; needs human interpretation', '[{"criterion":"First","marks":1},{"criterion":"Second","marks":1}]'::jsonb, '1 It cannot find copying from sources that are not in its database. 2 Common phrases may be flagged as matches.', '{}'::jsonb, null, null),
  ('3d21c908-1767-54a8-9df8-2774b52821e7', '097f1a82-44f9-5a67-9650-193cc4ea1c5b', 1, true, 'Any one (1): Turnitin; Antiplagiat; Unicheck; Copyleaks; Plagscan; MOSS; JPlag; Grammarly plagiarism checker', '[{"criterion":"Valid resource","marks":1}]'::jsonb, 'Turnitin.', '{}'::jsonb, null, null),
  ('e0d669ac-b0c3-5091-996d-b2d3450d76e5', 'd70a861e-72ee-5a39-aa62-2737741b4dfc', 1, true, 'Any two (1 each): automatic protection; permission / licence needed; quotation with author and source; life + 70 years; ideas not protected; software licence needed', '[{"criterion":"First","marks":1},{"criterion":"Second","marks":1}]'::jsonb, '1 Copyright is automatic from the moment the work is created. 2 Permission is needed to copy or publish the work.', '{}'::jsonb, null, null),
